options swap_delay=12 iteration=1000 ignore_burst_energy=true;

let _execute_action = execute_action;
fn execute_action(char_id number, action_id number, p map) {
  if action_id == .action.dash || (char_id == .keys.char.xilonen && action_id == .action.skill) {
    pick_up_crystallize("any");
  }
  return _execute_action(char_id, action_id, p);
}

target lvl=100 resist=0.1 radius=2 pos=0,2.4 hp=999999999;
energy every interval=480,720 amount=1;

active navia;
for let i=0; i<4; i=i+1 {
  if is_even(i) {
    ineffa skill, attack;
    columbina skill, burst;
  } else {
    ineffa skill, burst;
    columbina skill, charge, dash;
  }
  xilonen burst, skill, attack:2;
  navia burst;
  navia skill, attack:2, dash, attack:2, dash, attack:2;
  xilonen skill, attack:2;
  navia skill, attack:2, dash, attack:2, dash, attack:2;
  if (i / 3) * 3 == i {
    navia skill, attack;
  }
}

